+    // Verify via GET that the removal persisted.
+    let (_, _, get_body) =
+        request(build_caldav_router(accounts), Method::GET, &uri, Some(auth)).await;
+    assert!(
+        !get_body.contains("CATEGORIES:"),
+        "CATEGORIES removal must persist across reads"
+    );
+    let _ = (temp_dir, pool);
+}
